  // 3.0: Simple help and the install-statistics question
  'simple.help.g1.title': 'Collegare uno schermo',
  'simple.help.g1.s1': 'Sul televisore, tablet o computer che vuoi usare, apri il player: installa l’app Android oppure apri la pagina /player di questo sito nel browser.',
  'simple.help.g1.s2': 'Nessun televisore a portata di mano? Apri il player in un’altra scheda del browser per provarlo.',
  'simple.help.g1.s3': 'Il player mostra un codice di 6 cifre. Qui scegli «Aggiungi uno schermo» e inseriscilo.',
  'simple.help.g1.s4': 'Dai allo schermo un nome che riconosci, ad esempio «Vetrina».',
  'simple.help.g2.title': 'Cambiare cosa mostra uno schermo',
  'simple.help.g2.s1': 'Scegli «Cambia cosa mostra uno schermo» oppure tocca lo schermo in «I tuoi schermi».',
  'simple.help.g2.s2': 'Scegli «Sostituisci» per mostrare solo le novità, oppure «Aggiungi» per mantenere quello che è già in riproduzione.',
  'simple.help.g2.s3': 'Carica foto o video, scegli quelli caricati in precedenza o mostra lo stesso contenuto di un altro schermo.',
  'simple.help.g2.s4': 'Lo schermo si aggiorna in pochi secondi.',
  'simple.help.g3.title': 'Caricare foto e video',
  'simple.help.g3.s1': 'Scegli «Carica foto» e seleziona tutti i file che vuoi, oppure trascinali.',
  'simple.help.g3.s2': 'Spunta gli schermi che devono mostrarli, oppure togli tutte le spunte per tenerli per dopo.',
  'simple.help.g3.s3': 'Le foto restano 10 secondi ciascuna; i video vengono riprodotti fino alla fine.',
  'simple.help.q1': 'Cosa posso usare come schermo?',
  'simple.help.a1': 'Televisori Android, TV box e tablet, Fire TV, smart TV LG e Samsung, Raspberry Pi, Windows e ChromeOS, o qualsiasi dispositivo con un browser web.',
  'simple.help.q2': 'Il mio schermo non cambia. Cosa devo controllare?',
  'simple.help.a2': 'Controlla che lo schermo indichi «In riproduzione» nella pagina iniziale. Se indica «Offline», verifica che il dispositivo sia acceso e connesso a internet; riceverà le modifiche appena si riconnette.',
  'simple.help.q3': 'Cosa succede se cade internet?',
  'simple.help.a3': 'Gli schermi conservano i contenuti in locale e continuano a riprodurli. Le nuove modifiche arrivano quando torna la connessione.',
  'simple.help.q4': 'Quali file posso caricare?',
  'simple.help.a4': 'Foto (JPEG, PNG, GIF, WebP) e video (MP4 funziona meglio), oltre all’audio. I PDF si caricano dalla pagina Contenuti nella vista «Avanzata».',
  'simple.help.q5': 'Come rinomino o rimuovo uno schermo?',
  'simple.help.a5': 'Passa a «Avanzata» (in alto a destra), apri «Schermi», fai clic sullo schermo e usa Rinomina o Rimuovi in cima alla sua pagina.',
  'simple.help.q6': 'Posso mostrare cose diverse in diversi momenti della giornata?',
  'simple.help.a6': 'Sì: è «Programmazione», nella vista «Avanzata». La vista semplice mostra sempre lo stesso contenuto su uno schermo finché non lo cambi.',
  'simple.help.trial_q': 'Come funziona la prova gratuita?',
  'simple.help.trial_a': 'Hai 14 giorni del piano Pro con tutte le funzioni, senza carta. Al termine passi al piano Free: non viene eliminato nulla e gli schermi oltre il limite del piano Free vanno in pausa finché non scegli un piano.',
  'stats.prompt.title': 'Ci aiuti a capire quanto è diffuso ScreenTinker?',
  'stats.prompt.body': 'Poiché la maggior parte delle installazioni è privata, non sappiamo quanti schermi esistano. Condividendo invii un ID casuale, la versione e quanti schermi usi, nient’altro, mai. Puoi cambiare idea in qualsiasi momento nelle Impostazioni.',
  'stats.prompt.share': 'Condividi',
  'stats.prompt.no': 'No, grazie',
  'stats.prompt.thanks': 'Grazie: statistiche di installazione condivise',
