  'exp.how_title': 'Come viene calcolato il risultato',
  'exp.how_1': 'Ciò che ogni schermo ha davvero riprodotto viene dal proof-of-play, quindi uno schermo spento non viene contato come se mostrasse qualcosa. Un\'ora conta per una versione solo quando quella versione era l\'unica sullo schermo.',
  'exp.how_2': 'Per sede, ogni negozio viene confrontato con le sue vendite normali di prima del test, così un negozio grande non vince solo perché è grande. Per fascia oraria, le versioni si alternano e ruotano lungo la settimana, così nessuna versione prende tutte le ore di punta.',
  'exp.how_3': 'L\'intervallo mostrato (l\'intervallo al 95%) viene dal ricampionare giorni interi o negozi interi 2.000 volte. Quando non include lo zero, la differenza è probabilmente reale. "Servono circa N giorni in più" è una stima di quanto manca perché l\'intervallo sia abbastanza stretto da decidere.',
