  'sitecache.intro': 'Un piccolo computer sempre acceso in una sede scarica i tuoi media una volta sola, e gli schermi lì li prendono dalla rete locale invece che da internet.',
  'sitecache.how': 'Gli schermi controllano ogni file con la sua impronta e tornano a questo server se la cache è lenta, spenta o sbagliata: una cache può far risparmiare banda ma non lascerà mai uno schermo vuoto. I player web la usano dal prossimo riavvio; i player Android dal prossimo aggiornamento della playlist. Vedi docs/site-cache.md.',
