  'migrate.key_note': 'La chiave viene usata solo per questa importazione. Resta cifrata al massimo per qualche ora e viene eliminata al termine dell\'importazione. Basta l\'accesso in lettura.',
  'migrate.timezone_help': 'Usato per gli orari delle programmazioni quando la sorgente non indica in quale fuso orario si trova uno schermo.',
