  'migrate.field.region': 'Regione',
  'migrate.how.xibo': 'In Xibo, apri Administration, poi Applications, e aggiungi una Application con "Client Credentials" spuntato. Copia il suo Client ID e il Client Secret. Inserisci l\'indirizzo del tuo CMS (quello in cui accedi), per esempio https://cms.example.com.',
  'migrate.how.yodeck': 'In Yodeck, apri Account Settings, Advanced Settings, API Tokens e genera un token (piano Premium o Enterprise). Incollalo come etichetta:token. Yodeck non fornisce tramite la sua API le immagini e i documenti originali caricati: vengono elencati così puoi aggiungerli con l\'importazione zip. I video arrivano nella versione che Yodeck riproduce.',
  'migrate.how.optisigns': 'OptiSigns ha un\'API, ma non documenta alcun modo per scaricare i tuoi file, quindi una playlist arriverebbe vuota. Scarica i tuoi file da OptiSigns e usa l\'importazione zip: una cartella per playlist, oppure un playlists.csv.',
  'migrate.how.screencloud': 'In ScreenCloud Studio, apri Account Settings, poi la scheda Developer, e crea un token con permessi di lettura. Scegli la regione indicata lì (EU o US). ScreenCloud tiene le regole orarie sui singoli elementi dei canali; queste vengono elencate, non importate.',
  'migrate.how.anthias': 'Inserisci l\'indirizzo del tuo dispositivo Anthias, per esempio http://192.168.1.20. Se hai attivato l\'autenticazione, inserisci nome utente e password. Ogni dispositivo viene importato come uno schermo con una playlist.',
  'migrate.how.screenly': 'In Screenly, apri Settings, Security, Tokens e aggiungi un token. Arrivano playlist, etichette e schermi; le regole semplici su giorni e orari diventano programmazioni.',
  'migrate.how.generic_zip': 'Carica uno zip dei tuoi media. Ogni cartella diventa una playlist. Se vuoi, aggiungi playlists.csv (colonne: playlist, file, duration, order) e screens.csv (colonne: name, group, playlist).',
  'migrate.scanning': 'Lettura dei contenuti in corso. Gli account grandi richiedono qualche minuto.',
